 WHERE r.REQUEST_ID = #{requestId}

AND (
	r.STATUS_CODE IN ('REQ_01', 'REQ_02')
	OR EXISTS (
		SELECT 1
		  FROM ESTIMATES e
		 WHERE e.REQUEST_ID = r.REQUEST_ID
		   AND e.FIXER_NO   = #{userNo}
