mapper.update:
UPDATE REPAIR_REQUESTS
   SET STATUS_CODE = #{statusCode}
 WHERE REQUEST_ID = #{requestId}

UPDATE ESTIMATES
   SET STATUS = #{status}
 WHERE ESTIMATE_ID = #{estimateId}

UPDATE REPAIR_REQUESTS
SET CATEGORY_CODE = #{categoryCode}, TITLE = #{title}, CONTENT = #{content}, SERVICE_ADDRESS = #{serviceAddress},
VISIT_DATE = CASE WHEN #{visitDate} IS NULL OR #{visitDate} = '' THEN NULL ELSE TO_DATE(#{visitDate}, 'YYYY-MM-DD') END,
VISIT_TIME_CODE = #{visitTimeCode}
WHERE REQUEST_ID = #{requestId}
AND USER_NO = #{userNo}
AND STATUS_CODE IN ('REQ_01', 'REQ_02')

UPDATE REPAIR_REQUESTS

   SET STATUS_CODE = #{statusCode}

 WHERE REQUEST_ID = #{requestId}

   AND USER_NO = #{userNo}

   AND STATUS_CODE IN ('REQ_01', 'REQ_02')
